<?php
/**
 * Ticket page tab #development: linked repositories and their sync status
 * (git-sync-status.php), counts per Git event kind, manual branch links, the Git timeline
 * (git-timeline-event.php), the #git-files-dialog and, for non-viewers when the project has
 * repositories, #ticket-branch-dialog to link an existing branch.
 * Included by ticket.php, and rendered alone by TicketDevelopmentController::panel
 * (GET /tickets/{id}/development) to refresh the tab.
 * Expects $ticket, $project, $user and the variables from TicketDevelopment::data():
 * $ticketRepositories, $primaryRepository, $ticketBranches, $events, $developmentCounts.
 * $branchSuggestion is a suggested branch name: "feature/" + key + ASCII slug of the title.
 */
use App\Services\{DevelopmentPayload,GitPullRequest}; $branchSuggestion='feature/'.$ticket['key'].'-'.trim(substr(preg_replace('/[^a-z0-9]+/','-',strtolower((string)iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$ticket['title']))),0,60),'-'); ?>
<section class="panel ticket-development" id="development" data-ticket-panel aria-labelledby="ticket-tab-development">
 <div class="panel-header"><div><h2>Développement</h2><p>Branches, commits et pull requests liés à <?= e($ticket['key']) ?>.</p></div><?= icon('code') ?></div>
 <?php if($ticketRepositories): ?><p class="help-text">Dépôts du projet : <?php foreach($ticketRepositories as $repo): ?><span class="pill neutral"><?= $repo['provider']==='github'?'GitHub':'Bitbucket' ?> · <?= e($repo['repository']) ?><?= $primaryRepository && $primaryRepository['id']===$repo['id']?' · principal':'' ?></span> <?php endforeach; ?></p><?php else: ?><p class="help-text">Aucun dépôt Git n’est lié à ce projet. Un administrateur peut en associer un depuis Développement ou les paramètres du projet.</p><?php endif; ?>
 <?php if($ticketRepositories): ?><details class="git-connection-details" id="ticket-git-connection-status"><summary>Synchronisation et connexions</summary><?php foreach($ticketRepositories as $c) require ROOT.'/app/Views/partials/git-sync-status.php'; ?></details><?php endif; ?>
 <div class="development-counts"><?php foreach(DevelopmentPayload::KINDS as $kind=>$label): ?><button type="button" data-git-kind="<?= e($kind) ?>" aria-pressed="false"><?= icon(match($kind){'branch'=>'git-branch','commit'=>'git-commit','pull_request'=>'git-pull','build'=>'flask','deployment'=>'rocket'}) ?><strong><?= (int)($developmentCounts[$kind]??0) ?></strong><span><?= e($label) ?></span></button><?php endforeach; ?></div>
 <?php if(!$events): ?><p class="help-text">Ajoutez la clé <strong><?= e($ticket['key']) ?></strong> au nom d’une branche, au message d’un commit ou dans le titre ou la description d’une pull request.</p><?php endif; ?>
 <div class="ticket-development-actions"><button type="button" class="button subtle small-button" data-copy="<?= e($branchSuggestion) ?>"><?= icon('code') ?>Copier un nom de branche</button><?php if($ticketRepositories && $user['role']!=='viewer'): ?><button type="button" class="button primary small-button" data-open="ticket-branch-dialog"><?= icon('link') ?>Lier une branche existante</button><?php endif; ?><?php if($user['role']==='admin'): ?><a class="button subtle small-button" href="/development?project=<?= (int)$project['id'] ?>">Gérer les dépôts du projet <?= icon('arrow') ?></a><?php endif; ?></div>
 <?php if($ticketBranches): ?><details class="ticket-linked-branches" id="ticket-manual-branches"><summary>Liens manuels de branches · <?= count($ticketBranches) ?></summary><?php foreach($ticketBranches as $linked): ?><div class="ticket-linked-branch"><div><strong><?= e($linked['branch_name']) ?></strong><small><?= $linked['provider']==='github'?'GitHub':'Bitbucket' ?> · <?= e($linked['repository']) ?></small></div><?php if($user['role']!=='viewer'): ?><button type="button" class="button subtle small-button" data-git-sync-branch="<?= (int)$linked['id'] ?>">Synchroniser l’historique</button><form method="post" action="/tickets/<?= (int)$ticket['id'] ?>/development/links/<?= (int)$linked['id'] ?>/delete" data-ticket-branch-unlink><?= csrf() ?><button class="button subtle small-button" data-confirm="Retirer ce lien manuel ? Les éléments déjà reçus restent dans l’historique. Les références contenant la clé du ticket restent automatiques.">Retirer le lien</button></form><?php endif; ?></div><?php endforeach; ?></details><?php endif; ?>
 <div class="git-history-progress"><p class="help-text" role="status" aria-live="polite" data-git-history-status></p><button type="button" class="button subtle small-button" data-git-history-next hidden>Charger les PR plus anciennes</button></div>

 <div class="git-timeline-toolbar"><div><h3>Chronologie Git</h3><p class="help-text">Dernières observations connues · jusqu’à 20 par catégorie · dates en UTC.</p></div><button type="button" class="button subtle small-button" data-git-kind="all" aria-pressed="true">Tout afficher</button><label class="git-timeline-search">Rechercher dans le parcours<input type="search" data-git-timeline-search placeholder="Branche, commit, PR…"></label></div>
 <p class="help-text" data-git-timeline-result role="status" aria-live="polite"></p>
 <div class="git-timeline"><?php foreach(App\Services\TicketDevelopment::timeline($events) as $day=>$dayEvents): ?><section class="git-timeline-day" data-git-day><h4><?php if($day==='unknown'): ?>Date non fournie<?php else: ?><?= icon('calendar') ?><time datetime="<?= e($day) ?>" data-git-day-label><?= e((new DateTimeImmutable($day))->format('d/m/Y')) ?></time><?php endif; ?></h4><div class="git-day-items"><?php foreach($dayEvents as $event) require ROOT.'/app/Views/partials/git-timeline-event.php'; ?></div></section><?php endforeach; ?></div>
 <?php if(!$events): ?><p class="muted">Aucun élément reçu pour le moment.</p><?php endif; ?>
 <?php foreach(DevelopmentPayload::KINDS as $kind=>$label): if((int)($developmentCounts[$kind]??0)>20): ?><small class="help-text">Les 20 observations les plus récentes de cette rubrique sont affichées : <?= e($label) ?>.</small><?php endif; endforeach; ?>
 <details class="ticket-development-guide"><summary>Comment le lien se fait-il automatiquement ?</summary><ol><li>Liez le dépôt au projet <?= e(app_name()) ?>. Le dépôt principal est proposé par défaut ; les autres dépôts GitHub et Bitbucket du projet restent disponibles.</li><li>Dans GitHub ou Bitbucket, créez une branche contenant <strong><?= e($ticket['key']) ?></strong>, par exemple <code><?= e($branchSuggestion) ?></code>. Une branche créée sur votre ordinateur doit être poussée vers le dépôt distant.</li><li>Dans Développement → Configurer GitHub/Bitbucket, ouvrez les paramètres du webhook signé pour copier son URL et son secret. Activez les créations de branches, push et pull requests disponibles chez le fournisseur. Les nouvelles informations sont rapprochées à réception ; rouvrez ou actualisez ce panneau pour les consulter. Sans webhook, synchronisez les pages depuis Développement.</li></ol><p>La clé peut aussi être placée dans un message de commit ou dans le titre ou la description d’une pull request. Pour une branche existante sans clé, utilisez « Lier une branche existante ». Les liens manuels sont conservés lors des mises à jour reçues.</p><p class="help-text">Cette connexion suit le code. Elle n’importe pas les tickets « Issues » de GitHub ou Bitbucket.</p><button type="button" class="button subtle small-button" data-ticket-development-refresh>Actualiser ce panneau</button></details>
</section>
<dialog id="git-files-dialog" class="dialog git-files-dialog" aria-labelledby="git-files-title"><header class="dialog-header"><div><h2 id="git-files-title">Fichiers modifiés</h2><p class="help-text" data-git-files-title></p></div><button type="button" class="icon-button" data-close aria-label="Fermer"><?= icon('close') ?></button></header><p class="help-text" role="status" aria-live="polite" data-git-files-status></p><div class="git-files-list" data-git-files-list></div><div class="ticket-development-actions"><button type="button" class="button subtle small-button" data-git-files-previous hidden>Page précédente</button><button type="button" class="button subtle small-button" data-git-files-next hidden>Page suivante</button></div></dialog>
<?php if($ticketRepositories && $user['role']!=='viewer'): $selectedRepo=$primaryRepository['id']??(count($ticketRepositories)===1?$ticketRepositories[0]['id']:0); ?>
<dialog id="ticket-branch-dialog" class="dialog compact" aria-labelledby="ticket-branch-title"><header class="dialog-header"><h2 id="ticket-branch-title">Lier une branche à <?= e($ticket['key']) ?></h2><button type="button" class="icon-button" data-close aria-label="Fermer"><?= icon('close') ?></button></header>
 <form class="stack" method="post" action="/tickets/<?= (int)$ticket['id'] ?>/development/link" data-ticket-branch-form data-branches-url="/tickets/<?= (int)$ticket['id'] ?>/development/branches"><?= csrf() ?>
  <p class="help-text">La branche sera vérifiée chez le fournisseur, puis associée à ce ticket, même si son nom ne contient pas la clé.</p>
  <label>Dépôt du projet<select name="connection_id" required><option value="">Choisir un dépôt</option><?php foreach($ticketRepositories as $repo): ?><option value="<?= (int)$repo['id'] ?>" <?= $selectedRepo===$repo['id']?'selected':'' ?> data-repository-url="https://<?= $repo['provider']==='github'?'github.com':'bitbucket.org' ?>/<?= e($repo['repository']) ?>"><?= $repo['provider']==='github'?'GitHub':'Bitbucket' ?> · <?= e($repo['repository']) ?><?= $primaryRepository && $primaryRepository['id']===$repo['id']?' — principal':'' ?></option><?php endforeach; ?></select></label>
  <div class="ticket-development-actions"><button type="button" class="button subtle small-button" data-ticket-load-branches>Actualiser les branches</button><a class="button subtle small-button" target="_blank" rel="noopener noreferrer" data-ticket-repository-link hidden>Ouvrir le dépôt <?= icon('external') ?></a></div>
  <div class="branch-search"><label>Rechercher une branche<input type="search" maxlength="100" placeholder="Ex. : sitemap, staging…" data-ticket-branch-search data-dialog-ignore></label><button type="button" class="button subtle small-button" data-ticket-branch-search-button>Rechercher</button></div>
  <label>Branche<select name="branch_name" required data-ticket-branch-choices><option value="">Choisir une branche…</option></select><small>Classées du dernier commit le plus récent au plus ancien. Les dates inconnues sont placées à la fin.</small></label>
  <details class="branch-manual"><summary>Saisir un nom de branche manuellement</summary><label>Nom exact<input type="text" maxlength="1000" placeholder="feature/correction-sitemap" autocomplete="off" data-ticket-branch-manual><small>Sans URL ni préfixe refs/heads/.</small></label></details>
  <div class="ticket-development-actions"><button type="button" class="button subtle small-button" data-ticket-branches-previous hidden>Page précédente</button><button type="button" class="button subtle small-button" data-ticket-branches-next hidden>Page suivante</button></div>
  <p class="help-text" role="status" aria-live="polite" data-ticket-branch-status></p><div class="modal-actions"><button class="button primary" type="submit">Vérifier et lier la branche</button></div>
 </form>
</dialog>
